import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Object3D } = ctx.THREE;
  const group = new Group();

  let cleanup = () => {};
  let loadedMesh = null;
  let timelines = [];

  const loadAndSetup = async () => {
    try {
      const gltf = await ctx.glbLoader.loadGLB(config.meshUrl);
      loadedMesh = gltf.scene;
      group.add(loadedMesh);

      // Apply scene position from config
      group.position.set(
        config.scenePosition?.[0] ?? 0,
        config.scenePosition?.[1] ?? 0,
        config.scenePosition?.[2] ?? 0
      );

      // Setup interaction handlers
      setupInteractions();
    } catch (err) {
      console.error('Failed to load divider mesh:', err);
    }
  };

  const setupInteractions = () => {
    let hoverTimeline = null;

    const onHover = () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();
      timelines.push(hoverTimeline);

      // rise-in: subtle 0.15 scene units, power3.out, 0.7s
      hoverTimeline.to(
        group.position,
        {
          y: group.position.y + 0.15,
          duration: 0.7,
          ease: 'power3.out'
        },
        0
      );
    };

    const onHoverOut = () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();
      timelines.push(hoverTimeline);

      // Return to original position
      hoverTimeline.to(
        group.position,
        {
          y: config.scenePosition?.[1] ?? 0,
          duration: 0.7,
          ease: 'power3.out'
        },
        0
      );
    };

    const onClick = () => {
      ctx.emit('hub-home.select', {});
    };

    group.userData.handlers = {
      onHover,
      onHoverOut,
      onClick
    };
  };

  // Perform async load
  loadAndSetup();

  // Setup cleanup
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    timelines = [];

    if (loadedMesh) {
      loadedMesh.traverse(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  };

  return group;
}
